}

Method.Source:
/// <summary>
/// Created for the FSD: CB201 Rebate extension - External sell data
/// </summary>
/// <param name="sender">xFormRun</param>
/// <param name="e">FormEventArgs</param>
[FormEventHandler(formStr(TAMRebateTrans), FormEventType::PostRun)]
public static void TAMRebateTrans_OnPostRun(xFormRun sender, FormEventArgs e)
{
    FormStringControl transactionNumber = sender.design().controlName(formControlStr(TAMRebateTrans, TAMRebateTrans_RebateRefId));

    transactionNumber.registerOverrideMethod(methodStr(FormStringControl, jumpRef), methodStr(METTAMRebateTransForm_Extension, metJumpRefId), sender);
}

/// <summary>
/// Created for the FSD: CB201 Rebate extension - External sell data
/// </summary>
/// <param name = "_formControl">FormControl</param>
public void metJumpRefId(FormControl _formControl)
{
    Args                                args;
    MenuFunction                        menuFunction;
    FormDataSource                      fds;
    METRebateTransId                    extTransId;
    METRebateScanSupplierTable          externalSellData;

    args                = new Args();
    fds                 = _formControl.dataSourceObject();
    extTransId          = _formControl.valueStr();
    externalSellData    = METRebateScanSupplierTable::find(extTransId);

    args.record(externalSellData);
    args.caller(fds.formRun());
    args.menuItemName(menuitemDisplayStr(METExternalSellData));

    new menuFunction(menuItemDisplayStr(METExternalSellData), MenuItemType::Display).run(args);
}
